            nt_cps(f, s3 + 1, s4, c4b);
            nt_cps(f, s4 + 1, s5, c5b);
            bad = 0;
            if nt_nfc_is(c1, c2, out, tmp) == 0 {
                bad += 1;
            }
            if nt_nfc_is(c2, c2b, out, tmp) == 0 {
                bad += 2;
            }
            if nt_nfc_is(c3, c2, out, tmp) == 0 {
                bad += 4;
            }
            if nt_nfc_is(c4, c4b, out, tmp) == 0 {
                bad += 8;
            }
            if nt_nfc_is(c5, c4, out, tmp) == 0 {
                bad += 16;
            }
            if nt_nfd_is(c1, c3, out) == 0 {
                bad += 32;
            }
            if nt_nfd_is(c2, c3, out) == 0 {
                bad += 64;
            }
            if nt_nfd_is(c3, c3b, out) == 0 {
                bad += 128;
            }
            if nt_nfd_is(c4, c5, out) == 0 {
                bad += 256;
            }
            if nt_nfd_is(c5, c5b, out) == 0 {
                bad += 512;
            }
            crate::testport::assert_eq_at(bad, 0, "failed checks (bitmask)", line);
