#[test]
fn test_composition_exclusions_stay_decomposed() {
    // U+0958 decomposes to U+0915 U+093C and is in Full_Composition_Exclusion,
    // so NFC leaves it decomposed -- else normalizing twice would change it.
    let src: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let want: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let out: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let tmp: &mut crate::port::Cells = &mut crate::port::Cells::new();
    nt_lit(&crate::testport::text_blob("0958")[..], src);
    nt_lit(&crate::testport::text_blob("0915 093C")[..], want);
    crate::testport::assert_eq(nt_nfc_is(src, want, out, tmp), 1, "NFC(U+0958) is its decomposition");
    crate::testport::assert_eq(nt_nfd_is(src, want, out), 1, "and so is NFD");
    nt_lit(&crate::testport::text_blob("212B")[..], src);
    nt_lit(&crate::testport::text_blob("00C5")[..], want);
    crate::testport::assert_eq(nt_nfc_is(src, want, out, tmp), 1, "a singleton (angstrom sign) goes to its canonical equivalent");
}
