#[test]
fn test_ligatures_and_soft_hyphens_are_flags() {
    let src: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let want: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let out: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let tmp: &mut crate::port::Cells = &mut crate::port::Cells::new();
    nt_lit(&crate::testport::text_blob("FB00 FB01 FB02 FB03 FB04 FB05 FB06")[..], src);
    crate::port::cells_drop(out, 0);
    nz_nfc(src, 0, crate::port::cells_len(src), out, tmp, 1);
    nt_lit(&crate::testport::text_blob("66 66 66 69 66 6C 66 66 69 66 66 6C 73 74 73 74")[..], want);
    crate::testport::assert_eq(nt_same(out, want), 1, "FB00..FB06 expand with the ligature flag");
    crate::port::cells_drop(out, 0);
    nz_nfc(src, 0, crate::port::cells_len(src), out, tmp, 0);
    crate::testport::assert_eq(nt_same(out, src), 1, "and stay as they are without it");
    nt_lit(&crate::testport::text_blob("61 AD 62")[..], src);
    nt_lit(&crate::testport::text_blob("61 62")[..], want);
    crate::port::cells_drop(out, 0);
    nz_nfc(src, 0, crate::port::cells_len(src), out, tmp, 2);
    crate::testport::assert_eq(nt_same(out, want), 1, "U+00AD is dropped with the soft-hyphen flag");
    crate::port::cells_drop(out, 0);
    nz_nfc(src, 0, crate::port::cells_len(src), out, tmp, 0);
    crate::testport::assert_eq(nt_same(out, src), 1, "and kept without it");
    nt_lit(&crate::testport::text_blob("FB01 65 301")[..], src);
    nt_lit(&crate::testport::text_blob("66 69 E9")[..], want);
    crate::port::cells_drop(out, 0);
    nz_nfc(src, 0, crate::port::cells_len(src), out, tmp, 3);
    crate::testport::assert_eq(nt_same(out, want), 1, "flags compose with NFC: fi + e-acute");
}
